-- Script de Inserción de Datos de Prueba para ProtelApp (Corregido)
-- Versión: 1.1
-- Corrección: Se usan los nombres de tabla correctos en mayúsculas (ej: CLIENTE) para asegurar la compatibilidad y el correcto funcionamiento de los deletes y las inserciones.

-- Desactivar temporalmente la revisión de claves foráneas para permitir el borrado
SET FOREIGN_KEY_CHECKS=0;

-- Limpiar tablas existentes usando los nombres correctos
DELETE FROM `FACTIBILIDAD`;
DELETE FROM `CLIENTE`;
DELETE FROM `ESTADO_FACTIBILIDAD`;
DELETE FROM `ESTADO_CLIENTE`;

-- Reiniciar contadores de AUTO_INCREMENT usando los nombres correctos
ALTER TABLE `FACTIBILIDAD` AUTO_INCREMENT = 1;
ALTER TABLE `CLIENTE` AUTO_INCREMENT = 1;
ALTER TABLE `ESTADO_FACTIBILIDAD` AUTO_INCREMENT = 1;
ALTER TABLE `ESTADO_CLIENTE` AUTO_INCREMENT = 1;

-- Reactivar la revisión de claves foráneas
SET FOREIGN_KEY_CHECKS=1;

